-- =====================================================================
-- 0079 — CRM & RFQ (a new KMR App, for any company: each company sees only its own data)
--  • Leads and a sales pipeline, customers and suppliers with contacts, follow-ups and visit / call notes.
--  • RFQs that customers send: parts, quantities, due dates, a costing sheet per part (material, process, outsourced,
--    tooling, packing, overhead, margin) that works out the selling price.
--  • Supplier prices for the same RFQ side by side; the chosen supplier flows into the costing.
--  • Numbered quotations with revisions, terms and tax, status follow-up, and a printed quotation / costing sheet /
--    supplier comparison with the customer logo, unique reference number and format revision on every page.
--  • Sample data to validate the flow and delete again.
-- Needs 0078. Safe to re-run. Generated by scripts/make-crm.py.
-- =====================================================================
do $$ begin
  if to_regprocedure('console.msa_sample(uuid, text)') is null then raise exception 'Run 0077_msa_spc.sql first.'; end if;
  if to_regprocedure('public.kmr_app_sample(text, text, text)') is null then raise exception 'Run 0078_dev_sample_button.sql first.'; end if;
end $$;

insert into console.products (code, name, description, app_path, seat_label, current_version, sort_order) values
  ('crm', 'CRM & RFQ', 'Leads and pipeline, customers and suppliers, RFQ register with costing, supplier price comparison and numbered quotations with revisions', '/it/crm.html', 'users', '1.0.0', 14)
on conflict (code) do nothing;
insert into console.releases (product_code, version, notes) values
  ('crm', '1.0.0', 'CRM & RFQ: leads and pipeline, customers and suppliers, follow-ups, RFQ register, costing, supplier comparison, quotations with revisions, print') on conflict do nothing;
insert into console.prices (product_code, period, currency, unit_amount, min_seats, active, note)
select v.code, v.period, 'INR', v.amt, 3, true, 'Starting price list (0079) — per user, change in Console › Billing'
  from (values ('crm', 'month', 80), ('crm', 'year', 800)) v(code, period, amt)
 where not exists (select 1 from console.prices x where x.product_code = v.code and x.currency = 'INR' and x.period = v.period)
on conflict (product_code, period, currency) do nothing;
insert into public.app_listings (code, name, tagline, features, sort_order, is_active) values
  ('crm', 'CRM & RFQ', 'From first enquiry to a priced, numbered quotation: leads, customers, RFQs, costing and supplier prices in one place.',
   E'Leads, pipeline, customers, suppliers and follow-ups\nRFQ register with a costing sheet that works out the price\nSupplier price comparison and numbered quotations with revisions', 14, true)
on conflict (code) do update set name = excluded.name, tagline = excluded.tagline, features = excluded.features, is_active = true;

insert into console.app_features (product_code, name, detail, is_core, price_month, price_year, setup_fee, sort_order) values
  ('crm', 'Leads & customers', 'Leads and pipeline, customers and suppliers with contacts, follow-ups, calls and visits, dashboard', true, 20, 0, 6000, 10),
  ('crm', 'RFQ & costing', 'RFQ register with parts, quantities and due dates, costing sheet per part (material, process, outsourced, tooling, overhead, margin)', false, 20, 0, 6000, 20),
  ('crm', 'Quotations', 'Numbered quotations with revisions, tax and terms, status follow-up, print with logo and format revision', false, 15, 0, 4000, 30),
  ('crm', 'Supplier comparison', 'Supplier prices for each RFQ part side by side, best price and MOQ / lead-time flags, chosen supplier flows into the costing', false, 10, 0, 3000, 40)
on conflict (product_code, name) do nothing;
delete from console.app_features f where f.product_code = 'crm' and f.name = 'Core platform' and not exists (select 1 from console.invoice_lines il where il.feature_id = f.id);
update console.app_features set price_year = price_month * 10 where product_code = 'crm' and price_year = 0;
select console.sync_app_price('crm');

-- ---------- tables (every table holds one company's rows only: customer_id) ----------
create table if not exists console.crm_counters (
  customer_id uuid not null references console.customers(id) on delete cascade, key text not null, n bigint not null default 0, sample boolean not null default false, primary key (customer_id, key));
create table if not exists console.crm_settings (
  customer_id uuid primary key references console.customers(id) on delete cascade, data jsonb not null default '{}', sample boolean not null default false, updated_at timestamptz not null default now());
create table if not exists console.crm_parties (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  code text not null, kind text not null default 'customer' check (kind in ('customer', 'prospect', 'supplier')), name text not null, industry text, gstin text, pan text,
  address text, city text, state text, country text not null default 'India', pincode text, website text, payment_terms text, credit_days int check (credit_days is null or credit_days between 0 and 365),
  owner text, status text not null default 'active' check (status in ('active', 'inactive')), notes text,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, code));
create unique index if not exists crm_parties_name on console.crm_parties (customer_id, lower(name));
create table if not exists console.crm_contacts (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  party_id uuid not null references console.crm_parties(id) on delete cascade, name text not null, designation text, department text, email text, phone text, mobile text,
  is_primary boolean not null default false, notes text, sample boolean not null default false, created_at timestamptz not null default now());
create index if not exists crm_contacts_party on console.crm_contacts (party_id);
create table if not exists console.crm_leads (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  no text not null, party_id uuid references console.crm_parties(id) on delete set null, company text not null, contact_name text, designation text, phone text, email text, source text,
  stage text not null default 'New' check (stage in ('New', 'Contacted', 'Qualified', 'RFQ received', 'Quoted', 'Negotiation', 'Won', 'Lost')),
  product_interest text, value numeric(14,2) check (value is null or value >= 0), expected_close date, owner text, next_followup date, lost_reason text, notes text, closed_at timestamptz,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, no));
create index if not exists crm_leads_stage on console.crm_leads (customer_id, stage);
create table if not exists console.crm_rfqs (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  no text not null, customer_ref text, party_id uuid not null references console.crm_parties(id) on delete restrict, contact_id uuid references console.crm_contacts(id) on delete set null,
  lead_id uuid references console.crm_leads(id) on delete set null, received_on date not null default current_date, due_on date, status text not null default 'Received'
    check (status in ('Received', 'Costing', 'Quoted', 'Negotiation', 'Won', 'Lost', 'No quote')),
  priority text not null default 'Normal' check (priority in ('Normal', 'High', 'Urgent')), owner text, project text, currency text not null default 'INR', notes text, lost_reason text, decided_on date,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, no));
create index if not exists crm_rfqs_party on console.crm_rfqs (customer_id, party_id);
create index if not exists crm_rfqs_status on console.crm_rfqs (customer_id, status, due_on);
create table if not exists console.crm_rfq_items (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  rfq_id uuid not null references console.crm_rfqs(id) on delete cascade, seq int not null, part_no text, part_name text not null, drawing_no text, revision text, material text,
  qty numeric(14,3) not null default 1 check (qty > 0), annual_qty numeric(14,3) check (annual_qty is null or annual_qty >= 0), uom text not null default 'Nos',
  target_price numeric(14,4) check (target_price is null or target_price >= 0), cost jsonb not null default '{}', unit_cost numeric(14,4) not null default 0, unit_price numeric(14,2) not null default 0,
  remarks text, sample boolean not null default false, created_at timestamptz not null default now(), unique (rfq_id, seq));
create table if not exists console.crm_supplier_quotes (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  rfq_id uuid not null references console.crm_rfqs(id) on delete cascade, item_id uuid not null references console.crm_rfq_items(id) on delete cascade,
  supplier_id uuid not null references console.crm_parties(id) on delete restrict, what text not null default 'Bought-out part'
    check (what in ('Raw material', 'Bought-out part', 'Outsourced process', 'Tooling', 'Other')), price numeric(14,4) not null check (price >= 0), moq numeric(14,3) check (moq is null or moq >= 0),
  lead_days int check (lead_days is null or lead_days >= 0), valid_until date, payment_terms text, quote_ref text, received_on date, selected boolean not null default false, notes text,
  sample boolean not null default false, created_by text, created_at timestamptz not null default now());
create index if not exists crm_sq_item on console.crm_supplier_quotes (item_id);
create table if not exists console.crm_quotes (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  no text not null, rev int not null default 0 check (rev >= 0), rfq_id uuid not null references console.crm_rfqs(id) on delete cascade, party_id uuid not null references console.crm_parties(id) on delete restrict,
  contact_id uuid references console.crm_contacts(id) on delete set null, quote_date date not null default current_date, valid_until date,
  status text not null default 'draft' check (status in ('draft', 'sent', 'accepted', 'rejected', 'superseded')), currency text not null default 'INR',
  tax_name text not null default 'GST', tax_pct numeric(5,2) not null default 0 check (tax_pct between 0 and 100), payment_terms text, delivery_terms text, terms text, remarks text,
  lines jsonb not null default '[]', subtotal numeric(16,2) not null default 0, tax_amt numeric(16,2) not null default 0, total numeric(16,2) not null default 0,
  prepared_by text, sent_on date, decided_on date, sample boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (customer_id, no, rev));
create index if not exists crm_quotes_rfq on console.crm_quotes (rfq_id);
create table if not exists console.crm_activities (
  id uuid primary key default gen_random_uuid(), customer_id uuid not null references console.customers(id) on delete cascade,
  lead_id uuid references console.crm_leads(id) on delete cascade, party_id uuid references console.crm_parties(id) on delete cascade, rfq_id uuid references console.crm_rfqs(id) on delete cascade,
  kind text not null default 'call' check (kind in ('call', 'visit', 'email', 'meeting', 'note', 'task')), subject text not null, notes text, due_date date,
  done boolean not null default false, done_at timestamptz, owner text, sample boolean not null default false, created_by text, created_at timestamptz not null default now());
create index if not exists crm_act_open on console.crm_activities (customer_id, done, due_date);
do $$ declare t text; begin foreach t in array array['crm_counters','crm_settings','crm_parties','crm_contacts','crm_leads','crm_rfqs','crm_rfq_items','crm_supplier_quotes','crm_quotes','crm_activities'] loop
  execute format('alter table console.%I enable row level security', t);
  execute format('drop policy if exists %I on console.%I', t || '_staff', t);
  execute format('create policy %I on console.%I for all to authenticated using (console.is_staff()) with check (console.is_staff())', t || '_staff', t);
end loop; end $$;

